// Second pass for the four html/legal projects. PUT /projects/{id}/keys returns
// 400 "Action not supported by this type of project" on these - they are
// document-type projects, not key-value software projects - so each translation
// is written individually through PUT /projects/{id}/translations/{translation_id}.
//
// Custom translation statuses are also disabled in all four (HTTP 400 on create),
// so these strings receive the text fix only and stay unverified.
const PROJECTS = [
  ['7497898368b56f1d07ee46.54496723', 'MyImage - html/legal pages',    69],
  ['901014606819db6d0bc999.26230201', 'Mobitrace - html/legal pages',  60],
  ['18564477693fc9bba4cec8.54789459', 'My QR Code html',               32],
  ['46919453689d5d729a1e70.59972091', 'PDF Editor - html/legal pages', 21]
];

const qs = 'include_translations=1&disable_references=1&limit=500&pagination=cursor'
  + '&filter_translation_lang_ids=640,753';

return PROJECTS.map(function (p) {
  return { json: { project_id: p[0], project_name: p[1], expected: p[2],
    url: 'https://api.lokalise.com/api2/projects/' + p[0] + '/keys?' + qs } };
});

// Same deterministic rule set as the main pass, which was proved to reproduce
// the reviewed 471-string change set exactly (execution 556312). One output item
// per translation, since this endpoint writes a single translation per request.
const cfgAll = $('Plan').all().map(function (x) { return x.json; });
const META = {};
cfgAll.forEach(function (c) { META[c.project_id] = c; });

const errors = [];
const bodies = [];
for (const p of $input.all()) {
  const r = p.json || {};
  const st = r.statusCode;
  const b = (r.body !== undefined) ? r.body : r;
  if (st !== undefined && st !== 200) { errors.push({ status: st, body: JSON.stringify(b).slice(0, 300) }); continue; }
  bodies.push(b);
}

const TH = '\u0E00-\u0E7F';
const THC = new RegExp('[' + TH + ']');
const QPART = ['หรือไม่','อย่างไร','เท่าใด','เท่าไร','ไหม','อะไร','ทำไม','เมื่อใด','ที่ไหน','ใคร','กี่'];
const LOAN = [['โพรไฟล์','โปรไฟล์','loan-profile'],['อีเมล์','อีเมล','loan-email'],
  ['อัพโหลด','อัปโหลด','loan-upload'],['ลิงค์','ลิงก์','loan-link'],
  ['เวปไซต์','เว็บไซต์','loan-website'],['คุ้กกี้','คุกกี้','loan-cookie'],
  ['โปรโมชั่น','โปรโมชัน','loan-promotion']];

function applyRules(th) {
  const fixes = [];
  let out = th;
  if (out.indexOf('\u00a0') >= 0) { out = out.split('\u00a0').join(' '); fixes.push('ws-nbsp'); }
  if (out.indexOf('\u200b') >= 0) { out = out.split('\u200b').join(''); fixes.push('ws-zwsp'); }
  if (out.indexOf('\u2011') >= 0) { out = out.split('\u2011').join('-'); fixes.push('ws-nbhyphen'); }
  for (const L of LOAN) { if (out.indexOf(L[0]) >= 0) { out = out.split(L[0]).join(L[1]); fixes.push(L[2]); } }
  let n = out.replace(/QR\s*โค้ด/g, 'คิวอาร์โค้ด').replace(/รหัส\s*QR/g, 'คิวอาร์โค้ด');
  if (n !== out) { out = n; fixes.push('term-qrcode'); }
  if (/[\u0E50-\u0E59]/.test(out)) {
    out = out.replace(/[\u0E50-\u0E59]/g, function (c) { return String(c.charCodeAt(0) - 0x0E50); });
    fixes.push('num-thaidigits');
  }
  if (/[\u201c\u201d]/.test(out)) { out = out.replace(/[\u201c\u201d]/g, '"'); fixes.push('punct-quotes'); }
  if (out.indexOf('\u2026') >= 0) { out = out.split('\u2026').join('...'); fixes.push('punct-ellipsis'); }
  if (out.indexOf('กรุณา') >= 0) { out = out.split('กรุณา').join('โปรด'); fixes.push('tone-please'); }
  const thanRe = new RegExp('(?<![' + TH + '])ท่าน', 'g');
  if (thanRe.test(out) && out.indexOf('ผู้ท่าน') < 0) {
    out = out.replace(new RegExp('(?<![' + TH + '])ท่าน', 'g'), 'คุณ');
    fixes.push('tone-2ndperson');
  }
  n = out.replace(new RegExp('([' + TH + '])([A-Za-z0-9])', 'g'), '$1 $2')
         .replace(new RegExp('([A-Za-z0-9])([' + TH + '])', 'g'), '$1 $2');
  if (n !== out) { out = n; fixes.push('space-script'); }
  n = out.replace(new RegExp('ๆ(?=[' + TH + '])', 'g'), 'ๆ ');
  if (n !== out) { out = n; fixes.push('space-yamok'); }
  n = out.replace(/\sๆ/g, 'ๆ');
  if (n !== out) { out = n; fixes.push('space-yamok-before'); }
  n = out.replace(/ {2,}/g, ' ').trim();
  if (n !== out) { out = n; fixes.push('ws-collapse'); }
  if (/[^.]\.$/.test(out) && THC.test(out)) {
    out = out.replace(/\.$/, '').replace(/\s+$/, ''); fixes.push('punct-nofinalstop');
  }
  if (out.charAt(out.length - 1) === '?') {
    let hasQ = false;
    for (const q of QPART) { if (out.indexOf(q) >= 0) { hasQ = true; break; } }
    if (hasQ) { out = out.replace(/\?+$/, '').replace(/\s+$/, ''); fixes.push('punct-noquestionmark'); }
    else { fixes.push('FLAG-question-no-particle'); }
  }
  return { out: out, fixes: fixes };
}

const MTACC = { 'support@lokali.se': 1, 'support@lokalise.co': 1 };
const out = [];
const histogram = {};
const perProject = {};

for (const b of bodies) {
  const pid = String(b.project_id || '');
  const meta = META[pid] || {};
  if (!perProject[pid]) perProject[pid] = { project: meta.project_name || pid, expected: meta.expected, found: 0 };
  for (const k of (b.keys || [])) {
    if (k.is_archived === true) continue;
    if (k.is_plural === true) continue;
    let tgt = null;
    for (const t of (k.translations || [])) { if (t.language_iso === 'th') tgt = t; }
    if (!tgt) continue;
    const v = tgt.translation;
    const txt = (typeof v === 'string') ? v : JSON.stringify(v);
    if (!txt || !String(txt).trim()) continue;
    if (tgt.is_reviewed) continue;
    const who = tgt.modified_by_email || '';
    const stats = (tgt.custom_translation_statuses || []).map(function (x) { return x.title; });
    const sig = (stats.indexOf('MT_to_review') >= 0) || !!MTACC[who]
      || tgt.modified_by === 1 || tgt.modified_by === 2
      || !!tgt.is_unverified || !!tgt.is_fuzzy;
    if (!sig) continue;

    const res = applyRules(txt);
    const real = res.fixes.filter(function (f) { return f.indexOf('FLAG') !== 0; });
    if (real.length === 0 || res.out === txt) continue;
    for (const f of real) { histogram[f] = (histogram[f] || 0) + 1; }
    perProject[pid].found++;

    out.push({ json: {
      project_id: pid, project: meta.project_name || pid,
      key: (k.key_name || {}).web || (k.key_name || {}).other || '',
      translation_id: tgt.translation_id,
      original: txt, intended: res.out, rules: real.join('|'),
      put_url: 'https://api.lokalise.com/api2/projects/' + pid
        + '/translations/' + tgt.translation_id,
      payload: { translation: res.out },
      _audit: { histogram: histogram, per_project: perProject,
        total: out.length + 1, fetch_errors: errors }
    } });
  }
}

return out;

const src = $('Derive fixes').all().map(function (x) { return x.json; });
const items = $input.all();

const byProject = {};
let ok = 0, failed = 0, mismatched = 0;
const failures = [];

for (let i = 0; i < items.length; i++) {
  const r = items[i].json || {};
  const s = src[i] || {};
  const body = (r.body !== undefined) ? r.body : r;
  const tr = (body && body.translation) || null;
  const p = s.project || 'unknown';
  if (!byProject[p]) byProject[p] = { written: 0, failed: 0 };

  const good = r.statusCode === 200 && tr;
  if (good) {
    // The endpoint echoes the saved translation - compare it to what was sent.
    const saved = String(tr.translation || '');
    if (saved.trim() !== String(s.intended).trim()) {
      mismatched++;
      failures.push({ project: p, key: s.key, translation_id: s.translation_id,
        issue: 'saved value differs from intended', intended: s.intended, saved: saved });
    }
    ok++; byProject[p].written++;
  } else {
    failed++; byProject[p].failed++;
    failures.push({ project: p, key: s.key, translation_id: s.translation_id,
      http_status: r.statusCode,
      error: (typeof body === 'string' ? body : JSON.stringify(body)).slice(0, 250) });
  }
}

return [{ json: {
  verdict: (failed === 0 && mismatched === 0)
    ? 'CLEAN - every translation written and echoed back matching'
    : 'PROBLEMS - see failures',
  attempted: items.length, written: ok, failed: failed, value_mismatches: mismatched,
  per_project: byProject,
  histogram: (src[0] && src[0]._audit) ? src[0]._audit.histogram : null,
  failures: failures.slice(0, 25) } }];
